const tasks = Array.isArray($json.tasks) ? $json.tasks : [];
const now = new Date();
const dateParts = Object.fromEntries(new Intl.DateTimeFormat('en', { timeZone: 'Asia/Bangkok', year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(now).map(({ type, value }) => [type, value]));
const reminderDate = `${dateParts.year}-${dateParts.month}-${dateParts.day}`;
const endOfToday = new Date(`${reminderDate}T23:59:59.999+07:00`);
const reminders = new Map();

for (const item of tasks) {
  const email = String(item?.assignee?.email ?? '').trim().toLowerCase();
  const dueAt = new Date(item?.task?.dueAt);
  if (!email.includes('@') || Number.isNaN(dueAt.valueOf()) || dueAt > endOfToday) continue;
  const reminder = reminders.get(email) ?? { email, name: String(item.assignee.name ?? '').trim() || email, tasks: [] };
  reminder.tasks.push({
    title: String(item.task.title ?? '').trim() || 'Untitled assignment',
    meeting: String(item.meeting?.title ?? '').trim(),
    dueAt,
    url: String(item.task.url ?? '').trim(),
  });
  reminders.set(email, reminder);
}

const escapeHtml = (value) => String(value ?? '').replace(/[&<>"']/g, (character) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[character]);
return [...reminders.values()].map(({ email, name, tasks }) => {
  tasks.sort((left, right) => left.dueAt - right.dueAt);
  const items = tasks.map((task) => {
    const due = task.dueAt.toLocaleString('th-TH', { timeZone: 'Asia/Bangkok', dateStyle: 'medium', timeStyle: 'short' });
    const status = task.dueAt < now ? 'เกินกำหนด' : 'ครบกำหนดวันนี้';
    const meeting = task.meeting ? ` · ${escapeHtml(task.meeting)}` : '';
    const link = /^https?:\/\//i.test(task.url) ? ` · <a href="${escapeHtml(task.url)}">เปิดงาน</a>` : '';
    return `<li><strong>${escapeHtml(task.title)}</strong>${meeting}<br>${status}: ${escapeHtml(due)}${link}</li>`;
  }).join('');
  return { json: { eventKey: `task-reminder:${reminderDate}:${email}`, email, subject: `[Saranote] ${tasks.length} งานต้องติดตาม`, html: `<div style="font-family:Arial,sans-serif;line-height:1.6;color:#222"><p>เรียน ${escapeHtml(name)}</p><p>งานต่อไปนี้ครบกำหนดวันนี้หรือเกินกำหนดแล้ว:</p><ul>${items}</ul><p style="color:#666;font-size:12px">ข้อความแจ้งเตือนอัตโนมัติจาก Saranote</p></div>` } };
});
